CREATE OR REPLACE FUNCTION engmarq_private.documento_legacy_path(reference text, company uuid, origin text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE prefix text; object_path text;
BEGIN
  IF origin IS NULL OR origin !~ '^https://[A-Za-z0-9.-]+(:[0-9]+)?$' THEN
    RAISE EXCEPTION 'Explicit trusted Storage origin required';
  END IF;
  prefix := origin || '/storage/v1/object/public/documentos/';
  IF reference IS NULL OR left(reference,length(prefix)) <> prefix THEN
    RAISE EXCEPTION 'Unrecognized legacy document reference';
  END IF;
  object_path := substr(reference,length(prefix)+1);
  IF company IS NULL OR object_path !~ ('^' || company::text || '/(certificados/)?[A-Za-z0-9_-]+\.[A-Za-z0-9]+$') THEN
    RAISE EXCEPTION 'Invalid legacy document tenant/path';
  END IF;
  RETURN object_path;
END;
$function$

CREATE OR REPLACE FUNCTION engmarq_private.guard_catalogo_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor record;
  editable text[] := ARRAY['nome','descricao','active'];
BEGIN
  IF current_setting('role', true) IS DISTINCT FROM 'authenticated' THEN
    RETURN NEW;
  END IF;
  SELECT p.empresa_id, p.role, p.active, e.status AS company_status INTO actor
    FROM public.user_profiles p JOIN public.empresas e ON e.id = p.empresa_id
    WHERE p.id = auth.uid() FOR SHARE OF p, e;
  IF NOT FOUND OR NOT actor.active OR actor.company_status <> 'ativa'
     OR actor.role NOT IN ('empresa','gestor') OR NEW.empresa_id IS DISTINCT FROM actor.empresa_id THEN
    RAISE EXCEPTION 'Catalog write denied' USING ERRCODE = '42501';
  END IF;
  IF TG_TABLE_NAME = 'funcoes' THEN editable := editable || ARRAY['riscos']; END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.empresa_id IS DISTINCT FROM actor.empresa_id
       OR (to_jsonb(NEW) - editable) IS DISTINCT FROM (to_jsonb(OLD) - editable) THEN
      RAISE EXCEPTION 'Immutable catalog fields' USING ERRCODE = '42501';
    END IF;
  ELSIF NEW.active IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'New catalog must be active' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION engmarq_private.guard_colaborador_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor record;
BEGIN
  -- Infrastructure remains technical; no functional route uses these roles.
  IF current_setting('role', true) IS DISTINCT FROM 'authenticated' THEN
    RETURN NEW;
  END IF;
  SELECT p.empresa_id, p.role, p.active, e.status AS company_status INTO actor
    FROM public.user_profiles p JOIN public.empresas e ON e.id = p.empresa_id
    WHERE p.id = auth.uid() FOR SHARE OF p, e;
  IF NOT FOUND OR NOT actor.active OR actor.company_status <> 'ativa'
     OR actor.role NOT IN ('empresa', 'gestor') OR NEW.empresa_id <> actor.empresa_id THEN
    RAISE EXCEPTION 'Colaborador write denied' USING ERRCODE = '42501';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.active IS DISTINCT FROM true OR NEW.data_demissao IS NOT NULL THEN
      RAISE EXCEPTION 'New colaborador must be active' USING ERRCODE = '23514';
    END IF;
  ELSE
    IF OLD.empresa_id <> actor.empresa_id
       OR (to_jsonb(NEW) - ARRAY['nome','matricula','funcao_id','setor_id','ambiente_id','active','data_demissao'])
          IS DISTINCT FROM
          (to_jsonb(OLD) - ARRAY['nome','matricula','funcao_id','setor_id','ambiente_id','active','data_demissao']) THEN
      RAISE EXCEPTION 'Immutable colaborador fields' USING ERRCODE = '42501';
    END IF;
    IF (NOT OLD.active AND NEW.active)
       OR ((NEW.active, NEW.data_demissao) IS DISTINCT FROM (OLD.active, OLD.data_demissao)
           AND (NEW.active OR NEW.data_demissao IS NULL)) THEN
      RAISE EXCEPTION 'Deactivation requires active=false and dismissal date; reactivation is not supported'
        USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION engmarq_private.guard_documento_metadata()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor record;
BEGIN
  IF current_setting('role',true) IS DISTINCT FROM 'authenticated' THEN
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  SELECT p.empresa_id,p.role,p.active,e.status INTO actor
    FROM public.user_profiles p JOIN public.empresas e ON e.id=p.empresa_id
    WHERE p.id=auth.uid() FOR SHARE OF p,e;
  IF NOT FOUND OR NOT actor.active OR actor.status<>'ativa' OR actor.role NOT IN ('empresa','gestor') THEN
    RAISE EXCEPTION 'Document metadata write denied' USING ERRCODE='42501';
  END IF;
  IF TG_OP='DELETE' THEN
    IF OLD.empresa_id<>actor.empresa_id THEN RAISE EXCEPTION 'Foreign document' USING ERRCODE='42501'; END IF;
    RETURN OLD;
  END IF;
  IF NEW.empresa_id<>actor.empresa_id OR (TG_OP='UPDATE' AND (
    OLD.empresa_id<>actor.empresa_id OR NEW.id IS DISTINCT FROM OLD.id
    OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.empresa_id IS DISTINCT FROM OLD.empresa_id)) THEN
    RAISE EXCEPTION 'Immutable document identity or foreign tenant' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION engmarq_private.guard_empresa_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor record;
  editable text[] := ARRAY['razao_social','cnpj','setor','cidade','uf','responsavel','email','telefone','logo_url'];
BEGIN
  IF current_setting('role',true) IS DISTINCT FROM 'authenticated' THEN RETURN NEW; END IF;
  SELECT p.role,p.active,p.empresa_id INTO actor FROM public.user_profiles p WHERE p.id=auth.uid() FOR SHARE;
  IF NOT FOUND OR NOT actor.active THEN RAISE EXCEPTION 'Company write denied' USING ERRCODE='42501'; END IF;
  IF TG_OP='UPDATE' THEN
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'Immutable company fields' USING ERRCODE='42501';
    END IF;
    IF actor.role<>'admin' AND (actor.role NOT IN ('empresa','gestor') OR OLD.id<>actor.empresa_id
      OR OLD.status<>'ativa' OR (to_jsonb(NEW)-editable) IS DISTINCT FROM (to_jsonb(OLD)-editable)) THEN
      RAISE EXCEPTION 'Administrative company fields denied' USING ERRCODE='42501';
    END IF;
  ELSIF actor.role<>'admin' THEN
    RAISE EXCEPTION 'Only platform admin may create companies' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION engmarq_private.guard_profile_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor record;
BEGIN
  -- Trusted service_role provisioning and migration-owner maintenance remain
  -- explicit privileged operations. Browser requests use authenticated.
  IF current_setting('role', true) IS DISTINCT FROM 'authenticated' THEN
    RETURN NEW;
  END IF;

  SELECT p.id, p.role, p.empresa_id, p.active, e.status AS company_status
    INTO actor
    FROM public.user_profiles p JOIN public.empresas e ON e.id = p.empresa_id
    WHERE p.id = auth.uid()
    FOR SHARE OF p, e;

  IF NOT FOUND OR NOT actor.active OR actor.company_status <> 'ativa'
     OR actor.role NOT IN ('gestor', 'empresa')
     OR OLD.id = actor.id
     OR (to_jsonb(NEW) - ARRAY['role', 'active']) IS DISTINCT FROM
        (to_jsonb(OLD) - ARRAY['role', 'active']) THEN
    RAISE EXCEPTION 'Profile update denied' USING ERRCODE = '42501';
  END IF;

  IF (
    OLD.empresa_id <> actor.empresa_id OR NEW.empresa_id <> actor.empresa_id
    OR OLD.role = 'admin' OR NEW.role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Profile update denied' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION engmarq_private.guard_treinamento_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  actor record;
  editable text[];
BEGIN
  IF current_setting('role', true) IS DISTINCT FROM 'authenticated' THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  SELECT p.empresa_id,p.role,p.active,e.status INTO actor
    FROM public.user_profiles p JOIN public.empresas e ON e.id=p.empresa_id
    WHERE p.id=auth.uid() FOR SHARE OF p,e;
  IF NOT FOUND OR NOT actor.active OR actor.status <> 'ativa' OR actor.role NOT IN ('empresa','gestor') THEN
    RAISE EXCEPTION 'Training write denied' USING ERRCODE='42501';
  END IF;
  IF TG_OP='DELETE' THEN
    IF TG_TABLE_NAME <> 'matriz_treinamentos' OR OLD.empresa_id IS DISTINCT FROM actor.empresa_id THEN
      RAISE EXCEPTION 'History deletion denied' USING ERRCODE='42501';
    END IF;
    RETURN OLD;
  END IF;
  IF NEW.empresa_id IS DISTINCT FROM actor.empresa_id THEN
    RAISE EXCEPTION 'Tenant mismatch' USING ERRCODE='42501';
  END IF;
  editable := CASE WHEN TG_TABLE_NAME='treinamentos' THEN
    ARRAY['colaborador_id','treinamento_tipo_id','data_realizacao','data_vencimento','carga_horaria','instrutor','modalidade','certificado_url','status']
    ELSE ARRAY['obrigatorio'] END;
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-editable) IS DISTINCT FROM (to_jsonb(OLD)-editable) THEN
    RAISE EXCEPTION 'Immutable training fields' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$function$
